∀ {n : ℕ} {F : BfgsVerification.Vec n → ℝ} (R : BfgsVerification.AdmissibleBFGSRun n F) {r : ℕ}
  (V : ℕ → Matrix (Fin n) (Fin r) ℝ) (P : ℕ → BfgsVerification.Mat r) (k : ℕ),
  R.normalizedFrameEnergy V P k = ((P k)⁻¹.transpose * BfgsVerification.metricGram (R.hessian k) (V k) * (P k)⁻¹).trace

∀ {n : ℕ} {F : BfgsVerification.Vec n → ℝ} {K : Set (BfgsVerification.Vec n)} {fstar c₁ c₂ η : ℝ}
  (C : BfgsVerification.TransportedCertificate.PotentialBandCertificate F K fstar c₁ c₂ η) (hc₂ : c₂ < 1),
  (C.absorb hc₂).L = 2 * C.L ∧ (C.absorb hc₂).δ = min C.δ (C.L + 1)⁻¹

∀ {n : ℕ} {F : BfgsVerification.Vec n → ℝ} {K : Set (BfgsVerification.Vec n)} {fstar c₁ c₂ η : ℝ}
  (C : BfgsVerification.TransportedCertificate.PotentialBandCertificate F K fstar c₁ c₂ η) (hc₂ : c₂ < 1)
  (x : BfgsVerification.Vec n), (C.absorb hc₂).W x = Real.exp (C.Ψ x) • C.W x

∀ {n : ℕ} (H : BfgsVerification.Mat n) (g y : BfgsVerification.Vec n) (α : ℝ),
  α ≠ 0 →
    BfgsVerification.metricEnergy H g ≠ 0 →
      -BfgsVerification.dot y (Matrix.mulVec H g) / BfgsVerification.metricEnergy H g ≠ 0 →
        let q := BfgsVerification.metricEnergy H g;
        let β := -BfgsVerification.dot y (Matrix.mulVec H g) / q;
        let v := Matrix.mulVec H g;
        BfgsVerification.inverseBFGS H (BfgsVerification.bfgsStep H g α) y =
          (1 + (β * q)⁻¹ • BfgsVerification.outer v y) * H * (1 + (β * q)⁻¹ • BfgsVerification.outer y v) +
            (α / (β * q)) • BfgsVerification.outer v v
